def months_between(a, b):
    ya, ma = map(int, a[:7].split('-')); yb, mb = map(int, b[:7].split('-'))
    return (yb - ya) * 12 + (mb - ma)


def fa_opening():
    out = []
    for name, acq, cost, life, salvage in FA:
        start = acq[:7]
        used = months_between(start, CUTOFF) + 1
        accum = min(cost - salvage, round((cost - salvage) / life * min(used, life), 2))
        out.append(dict(name=name, acq=acq, cost=cost, life=life, salvage=salvage, start=start, used=used, accum=accum, intangible=('биет бус' in name), land=False, rou=False))
    return out


# Нээлтийн бараа: 120 барааны 60-140 ш WH-01, 40 бараа 5-30 ш дэлгүүрүүдэд — өртөг = ITEMS.cost × 0.97..1.03
def opening_stock():
    out = []
    for i, it in enumerate(ITEMS[:200]):
        if it.get('service'):
            continue
        if i < 120:
            out.append((it['code'], 'WH-01', R.randint(60, 140) if it['cost'] < 100000 else R.randint(8, 30), round(it['cost'] * R.uniform(0.97, 1.03) / 10) * 10))
        if i % 5 == 0:
            out.append((it['code'], 'WH-02', R.randint(5, 30), round(it['cost'] * R.uniform(0.97, 1.03) / 10) * 10))
        if i % 7 == 0:
            out.append((it['code'], 'WH-03', R.randint(5, 20), round(it['cost'] * R.uniform(0.97, 1.03) / 10) * 10))
    out.append(('IMP-EXP', 'WH-01', 400, 95000))
    return out


